package com.clavis.reader;

import android.app.Activity;
import android.content.Intent;
import android.os.SystemClock;
import android.view.View;
import android.widget.FrameLayout;

/** Exercises real tab changes and retained player views without starting playback. */
final class NavigationChecks {
 static String run(ReaderChecks test)throws Exception{
  FeedTagChecks.run(test.getTargetContext());
  MainActivity a=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  try{
   test.waitForIdleSync();try(java.io.InputStream input=a.getAssets().open("speech/english-model.zip");java.util.zip.ZipInputStream model=new java.util.zip.ZipInputStream(input)){require(model.getNextEntry()!=null,"Bundled speech model is a real ZIP, not an LFS pointer");}final FrameLayout[] window={null};final View[] pillItem={null};
   test.runOnMainSync(()->{require(a.navigation!=null,"Navigation host exists");window[0]=a.navigation.window;pillItem[0]=window[0].findViewWithTag("bottom:Home");require(pillItem[0]!=null,"Bottom pill exists");});
   test.runOnMainSync(()->{require(window[0].findViewWithTag("bottom:News")!=null,"News is in the pill");require(window[0].findViewWithTag("bottom:Journals")!=null,"Articles is in the pill");require(window[0].findViewWithTag("bottom:Browser")==null,"Browser is outside the pill");require(window[0].findViewWithTag("bottom:Downloads")==null,"Downloads is outside the pill");require(SharedDownloads.relocateLegacy("content://com.android.externalstorage.documents/tree/primary%3AClavis/document/primary%3AClavis%2FBook.m4b").contains("primary%3AClavis%20%2B%2FBook.m4b"),"Saved book URI migrates to Clavis");try{String json=new org.json.JSONObject().put("uri","content://com.android.externalstorage.documents/tree/primary%3AClavis/document/primary%3AClavis%2FBook.m4b").toString();require(!SharedDownloads.relocateLegacy(json).contains("primary%3AClavis"),"JSON-escaped library URI migrates completely");}catch(org.json.JSONException e){throw new AssertionError(e);}require(SharedDownloads.relocateLegacy("primary:ClavisOther/Book").equals("primary:ClavisOther/Book"),"Other folders are preserved");});
   test.runOnMainSync(()->{java.util.HashSet<String> populated=new java.util.HashSet<>();for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Journals")&&!feed.items.isEmpty())populated.add(feed.title);for(String title:new String[]{"New England Journal of Medicine","The Lancet","JAMA","The BMJ","Nature","Science","Annals of Internal Medicine"})require(populated.contains(title),title+" has real journal entries after upgrade");for(int n=0;n<a.bar.getChildCount();n++){View view=a.bar.getChildAt(n);if(view instanceof android.widget.LinearLayout)for(int k=0;k<((android.widget.LinearLayout)view).getChildCount();k++){View tab=((android.widget.LinearLayout)view).getChildAt(k);if(tab instanceof android.widget.TextView)require(tab.getHeight()>=a.dp(44),"Top tabs have padded touch height");}}});
   String[] routes={"Home","Audio","Podcasts","News","Journals","Browser","Downloads"};
   long firstFrame=0;
   for(String route:routes){if(!route.equals("Home")&&!route.equals("Browser")&&!route.equals("Downloads"))firstFrame=Math.max(firstFrame,tapToDraw(test,a,route));else test.runOnMainSync(()->a.navigateBottom(route));test.waitForIdleSync();test.runOnMainSync(()->{require(a.navigation.window==window[0],route+" keeps the same activity window");require(window[0].findViewWithTag("bottom:Home")==pillItem[0],route+" keeps the same bottom pill");require(a.navigation.saved.containsKey(route),route+" retains its section view");});}
   long[] slowest={0};
   for(int repeat=0;repeat<3;repeat++)for(String route:routes){test.runOnMainSync(()->{FrameLayout expected=a.navigation.saved.get(route).frame;long start=SystemClock.elapsedRealtime();a.navigateBottom(route);slowest[0]=Math.max(slowest[0],SystemClock.elapsedRealtime()-start);require(a.mainFrame==expected,route+" restores the existing view");require(expected.getVisibility()==View.VISIBLE,route+" becomes visible");});test.waitForIdleSync();}
   test.runOnMainSync(()->a.nowPlaying(new Book("navigation-check:fixture","Navigation player fixture","Audio")));test.waitForIdleSync();
   test.runOnMainSync(()->{require(a.screen.equals("Player"),"Player opens in the same activity");require(pillItem[0].isShown(),"Bottom pill stays visible in player");require(a.body.getPaddingBottom()>=a.dp(90),"Player reserves space above navigation");a.navigateBottom("Home");});test.waitForIdleSync();
   test.runOnMainSync(()->{a.navigateBottom("Audio");require(a.screen.equals("Player"),"Returning to Audio retains the player");require(pillItem[0].isShown(),"Player navigation remains visible after returning");});
   require(slowest[0]<250,"Cached tab changes should finish in under 250 ms; slowest was "+slowest[0]+" ms");
   long cachedFrame=0;for(String route:new String[]{"Home","Audio","Podcasts","News","Journals"})cachedFrame=Math.max(cachedFrame,tapToDraw(test,a,route));
   for(String kind:new String[]{"News","Journals"})checkStoryCenter(test,a,kind);
   checkFloatingTop(test,a);checkFeedTabDirection(test,a);
   require(firstFrame<750,"First tab opening must draw promptly; slowest was "+firstFrame+" ms");
   return "Navigation checks passed: one window, persistent PNG pill, all seven retained sections, player spacing, leading journals and animated story centering. Slowest first-visit tap-to-draw: "+firstFrame+" ms; cached tap-to-draw: "+cachedFrame+" ms; cached view restore: "+slowest[0]+" ms.\n";
  }finally{test.runOnMainSync(a::finish);}
 }
 static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 static void checkStoryCenter(ReaderChecks test,MainActivity a,String kind)throws Exception{
  test.runOnMainSync(()->a.navigateBottom(kind));test.waitForIdleSync();final FeedPosts.PostHolder[] holder={null};final androidx.recyclerview.widget.RecyclerView[] list={null};
  for(int n=0;n<80&&holder[0]==null;n++){test.runOnMainSync(()->{View view=a.root.findViewWithTag("feed-story-list");if(view instanceof androidx.recyclerview.widget.RecyclerView){list[0]=(androidx.recyclerview.widget.RecyclerView)view;if(list[0].getChildCount()>0){androidx.recyclerview.widget.RecyclerView.ViewHolder found=list[0].getChildViewHolder(list[0].getChildAt(0));if(found instanceof FeedPosts.PostHolder)holder[0]=(FeedPosts.PostHolder)found;}}});if(holder[0]==null)Thread.sleep(50);}
  require(holder[0]!=null,kind+" story card loads");test.runOnMainSync(()->{FeedScreens.goToTop(a);View tags=a.root.findViewWithTag("feed-tag-strip");require(tags instanceof android.widget.LinearLayout,kind+" tags appear below the top menu");android.widget.LinearLayout strip=(android.widget.LinearLayout)tags;require(strip.getChildCount()>=3,kind+" tag row fills available space with All, recent tags, and more");require(((android.widget.TextView)strip.getChildAt(0)).getText().toString().equals("All"),kind+" All shortcut is first");String moreLabel=((android.widget.TextView)strip.getChildAt(strip.getChildCount()-1)).getText().toString();require(moreLabel.equals("Show more")||moreLabel.matches("\\+\\d+ more"),kind+" more tags remain available with an overflow count");require(strip.getChildAt(0).getHeight()<=a.dp(28),kind+" tags use compact badges");View menu=EpisodeSummaryChecks.described(a.bar,"Feed actions");require(menu!=null,kind+" corner menu exists");menu.performClick();});test.waitForIdleSync();require(menuTextVisible(test,"Sort by"),kind+" corner menu includes Sort by");test.sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);Thread.sleep(250);test.waitForIdleSync();test.runOnMainSync(()->{FeedPosts.PostHolder post=holder[0];int[] cardAt=new int[2],authorAt=new int[2],websiteAt=new int[2];post.card.getLocationOnScreen(cardAt);post.author.getLocationOnScreen(authorAt);post.read.getLocationOnScreen(websiteAt);require(Math.abs(authorAt[0]+post.author.getWidth()/2-cardAt[0]-post.card.getWidth()/2)<=a.dp(2),kind+" author is centered");require(websiteAt[0]>authorAt[0]&&Math.abs(websiteAt[1]-authorAt[1])<=a.dp(2),kind+" website occupies the right side beside the centered author");require(post.previous.getLeft()<post.counter.getLeft()&&post.counter.getLeft()<post.next.getLeft(),kind+" paging controls are grouped in order on the left");post.pager.setCurrentItem(1,true);});Thread.sleep(600);test.waitForIdleSync();
  test.runOnMainSync(()->{require(a.bar.getVisibility()==View.GONE,kind+" header hides when reading");int center=holder[0].card.getTop()+holder[0].card.getHeight()/2,target=(list[0].getHeight()-list[0].getPaddingBottom())/2;require(Math.abs(center-target)<=a.dp(10),kind+" story settles at the center; difference "+(center-target));});
  int[] point=new int[2];test.runOnMainSync(()->{list[0].getLocationOnScreen(point);point[0]+=list[0].getWidth()/2;point[1]+=list[0].getHeight()/3;});long now=android.os.SystemClock.uptimeMillis();for(int step=0;step<5;step++){int action=step==0?android.view.MotionEvent.ACTION_DOWN:step==4?android.view.MotionEvent.ACTION_UP:android.view.MotionEvent.ACTION_MOVE;android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now+step*30,action,point[0],point[1]+step*a.dp(20),0);test.sendPointerSync(event);event.recycle();}Thread.sleep(350);test.waitForIdleSync();test.runOnMainSync(()->{require(a.bar.getVisibility()==View.VISIBLE&&a.bar.getHeight()>=a.dp(60),kind+" scroll-up restores the top panel, even at the first card; visibility="+a.bar.getVisibility()+", height="+a.bar.getHeight()+chromeState(a));holder[0].pager.setCurrentItem(0,true);});Thread.sleep(600);test.waitForIdleSync();test.runOnMainSync(()->require(a.bar.getVisibility()==View.VISIBLE,kind+" header returns with the cover"));
 }
 static void checkFloatingTop(ReaderChecks test,MainActivity a)throws Exception{
  test.runOnMainSync(()->{a.navigateBottom("News");require(EpisodeSummaryChecks.described(a.bar,"Go to top")==null,"Go to top is removed from the toolbar");});Thread.sleep(300);
  final androidx.recyclerview.widget.RecyclerView[] list={null};test.runOnMainSync(()->{list[0]=(androidx.recyclerview.widget.RecyclerView)a.root.findViewWithTag("feed-story-list");list[0].scrollToPosition(0);});Thread.sleep(300);test.runOnMainSync(()->{ScrollChrome.Controller chrome=ScrollChrome.active.get(list[0]);require(chrome!=null,"Feed scroll controller exists");chrome.top.scrolled(-1);require(!chrome.top.visible,"Go to top stays hidden on the first two pages");list[0].scrollToPosition(8);});Thread.sleep(400);
  int[] point=new int[2];test.runOnMainSync(()->{list[0].getLocationOnScreen(point);point[0]+=list[0].getWidth()/2;point[1]+=list[0].getHeight()/3;});long now=SystemClock.uptimeMillis();for(int n=0;n<6;n++){android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now+n*45,n==0?0:n==5?1:2,point[0],point[1]+n*a.dp(20),0);test.sendPointerSync(event);event.recycle();}Thread.sleep(300);
  test.runOnMainSync(()->{View pill=a.mainFrame.findViewWithTag("floating-go-to-top");require(pill!=null&&pill.isShown(),"Scrolling upward shows the floating Go to top pill");pill.performClick();});
  for(int n=0;n<80;n++){final boolean[] done={false};test.runOnMainSync(()->done[0]=!list[0].canScrollVertically(-1));if(done[0])break;Thread.sleep(50);}test.runOnMainSync(()->{require(!list[0].canScrollVertically(-1),"Floating pill returns to the top; first="+((androidx.recyclerview.widget.LinearLayoutManager)list[0].getLayoutManager()).findFirstVisibleItemPosition()+", childTop="+(list[0].getChildCount()>0?list[0].getChildAt(0).getTop():-999)+", padding="+list[0].getPaddingTop()+", state="+list[0].getScrollState());require(!a.mainFrame.findViewWithTag("floating-go-to-top").isShown(),"Floating pill hides at the top");});
 }
 static void checkFeedTabDirection(ReaderChecks test,MainActivity a)throws Exception{final FrameLayout[] frames=new FrameLayout[2];test.runOnMainSync(()->FeedScreens.show(a,"News",false));awaitFeedLoaded(test,a);test.runOnMainSync(()->{frames[0]=a.mainFrame;require(a.root.findViewWithTag("feed-loading")==null,"Popular has loaded before switching");FeedScreens.switchTab(a,"News",true);require(a.mainFrame.getTranslationX()==0&&a.bar.getTranslationX()==0,"My list keeps the top panel stationary");});awaitFeedLoaded(test,a);test.runOnMainSync(()->{frames[1]=a.mainFrame;FeedScreens.switchTab(a,"News",false);require(a.mainFrame==frames[0],"Popular restores the same loaded view");require(a.root.findViewWithTag("feed-loading")==null,"Returning to Popular has no loading placeholder");require(a.mainFrame.getTranslationX()==0&&a.bar.getTranslationX()==0,"Popular keeps the top panel stationary");});Thread.sleep(300);test.runOnMainSync(()->{FeedScreens.switchTab(a,"News",true);require(a.mainFrame==frames[1],"My list restores the same loaded view");require(a.root.findViewWithTag("feed-loading")==null,"Returning to My list has no loading placeholder");});Thread.sleep(300);test.runOnMainSync(()->FeedScreens.switchTab(a,"News",false));Thread.sleep(300);}
 static void awaitFeedLoaded(ReaderChecks test,MainActivity a)throws Exception{for(int n=0;n<160;n++){final boolean[] loaded={false};test.runOnMainSync(()->loaded[0]=a.root.findViewWithTag("feed-loading")==null);if(loaded[0])return;Thread.sleep(50);}throw new AssertionError("Feed initial load timed out");}
 static String chromeState(MainActivity a){ScrollChrome.Controller c=ScrollChrome.active.get(ScrollChrome.scroll(a.root));if(c==null)return "; no controller";StringBuilder out=new StringBuilder("; hidden="+c.hidden+", fraction="+c.fraction+", suspended="+c.suspended);for(ScrollChrome.Header h:c.headers)out.append(" [original=").append(h.originalHeight).append(", stored=").append(h.height).append(", actual=").append(h.view.getHeight()).append(", lp=").append(h.view.getLayoutParams().height).append("]");return out.toString();}
 static boolean menuTextVisible(ReaderChecks test,String text)throws Exception{for(int n=0;n<40;n++){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null&&!root.findAccessibilityNodeInfosByText(text).isEmpty())return true;Thread.sleep(50);}return false;}
 static long tapToDraw(ReaderChecks test,MainActivity a,String route)throws Exception{
  java.util.concurrent.CountDownLatch drawn=new java.util.concurrent.CountDownLatch(1);int[] point=new int[2];long[] elapsed={0},start={0};
  android.view.ViewTreeObserver.OnDrawListener[] listener={null};
  test.runOnMainSync(()->{View button=a.navigation.window.findViewWithTag("bottom:"+route);require(button!=null&&button.isShown(),route+" pill item is visible");require(((android.widget.ImageButton)button).getImageTintList()==null,route+" PNG retains its original colors");button.getLocationOnScreen(point);point[0]+=button.getWidth()/2;point[1]+=button.getHeight()/2;
   listener[0]=()->{if(start[0]>0&&NavigationHost.key(a.screen,a.bookBrowse).equals(route)&&elapsed[0]==0){elapsed[0]=android.os.SystemClock.elapsedRealtime()-start[0];a.navigation.window.post(()->{if(a.navigation.window.getViewTreeObserver().isAlive())a.navigation.window.getViewTreeObserver().removeOnDrawListener(listener[0]);drawn.countDown();});}};a.navigation.window.getViewTreeObserver().addOnDrawListener(listener[0]);});
  start[0]=android.os.SystemClock.elapsedRealtime();long now=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,android.view.MotionEvent.ACTION_DOWN,point[0],point[1],0),up=android.view.MotionEvent.obtain(now,now+20,android.view.MotionEvent.ACTION_UP,point[0],point[1],0);try{test.sendPointerSync(down);test.sendPointerSync(up);}finally{down.recycle();up.recycle();}
  require(drawn.await(5,java.util.concurrent.TimeUnit.SECONDS),route+" draws after tapping");return elapsed[0];
 }
}
